import React,{useEffect,useState} from 'react';
import {Navigate,NavLink,Route,Routes,useLocation,useNavigate,useParams} from 'react-router-dom';
import {LayoutDashboard,BriefcaseBusiness,ClipboardCheck,FolderOpen,ChartNoAxesCombined,Settings,Search,Bell,Plus,Menu,ChevronDown,ArrowUpRight,Clock3,AlertTriangle,CheckCircle2,FileText,Users,LogOut,Upload,Download,ShieldCheck,X,LoaderCircle,PanelLeftClose} from 'lucide-react';
import {AreaChart,Area,XAxis,YAxis,Tooltip,ResponsiveContainer,BarChart,Bar,CartesianGrid} from 'recharts';
const API=(import.meta.env.VITE_API_URL||'http://localhost:8000/api').trim().replace(/\/+$/,'');
function fetchWithTimeout(url,options={},timeoutMs=20000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);return fetch(url,{...options,signal:controller.signal}).catch(error=>{if(error.name==='AbortError')throw Error('The backend request timed out. Check that the Render backend is awake and try again.');throw Error('Could not connect to the backend. Verify VITE_API_URL and the backend CORS settings.');}).finally(()=>clearTimeout(timer))}
const readSavedUser=()=>{try{return JSON.parse(sessionStorage.getItem('user')||localStorage.getItem('user')||'null')}catch{return null}};
function App(){
 const navigate=useNavigate(),location=useLocation();
 const [token,setToken]=useState(()=>sessionStorage.getItem('token')||localStorage.getItem('token'));
 const [user,setUser]=useState(readSavedUser),[collapsed,setCollapsed]=useState(false),[toast,setToast]=useState(''),[loading,setLoading]=useState(false),[notificationOpen,setNotificationOpen]=useState(false),[notificationData,setNotificationData]=useState({items:[],unread_count:0}),[checking,setChecking]=useState(()=>Boolean(sessionStorage.getItem('token')||localStorage.getItem('token')));
 const logout=()=>{sessionStorage.removeItem('token');sessionStorage.removeItem('user');localStorage.removeItem('token');localStorage.removeItem('user');setToken(null);setUser(null);setChecking(false)};
 useEffect(()=>{const saved=sessionStorage.getItem('token')||localStorage.getItem('token');if(!saved){setChecking(false);return}fetchWithTimeout(API+'/auth/me',{headers:{Authorization:`Bearer ${saved}`}}).then(async r=>{if(!r.ok)throw Error('session expired');const u=await r.json();sessionStorage.setItem('token',saved);sessionStorage.setItem('user',JSON.stringify(u));localStorage.removeItem('token');localStorage.removeItem('user');setToken(saved);setUser(u)}).catch(logout).finally(()=>setChecking(false))},[]);
 const req=async(path,opts={})=>{const r=await fetchWithTimeout(API+path,{...opts,headers:{...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(token?{Authorization:`Bearer ${token}`}:{ }),...opts.headers}});if(r.status===401){logout();throw Error('Your session expired. Please sign in again.')}if(!r.ok){let e;try{e=await r.json()}catch{};const detail=e?.detail;throw Error(typeof detail==='string'?detail:detail?.message||`API request failed (${r.status}) at ${path}`)}return r.status===204?null:r.json()};
 useEffect(()=>{if(!token)return;fetch(API+'/notifications',{headers:{Authorization:'Bearer '+token}}).then(r=>r.ok?r.json():null).then(v=>{if(v)setNotificationData(v)}).catch(()=>{})},[token]);
const login=async(email,password)=>{setLoading(true);try{const body=new URLSearchParams({username:email.trim(),password});const r=await fetchWithTimeout(API+'/auth/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok){if(r.status===401)throw Error('Invalid email or password.');if(r.status===404)throw Error('Login endpoint not found. Check that VITE_API_URL points to the backend API base URL.');let detail='';try{const e=await r.json();detail=typeof e.detail==='string'?e.detail:''}catch{}throw Error(detail||`Sign-in request failed (${r.status}). Check the backend API route.`)}const data=await r.json();sessionStorage.setItem('token',data.access_token);sessionStorage.setItem('user',JSON.stringify(data.user));localStorage.removeItem('token');localStorage.removeItem('user');setToken(data.access_token);setUser(data.user);navigate('/',{replace:true})}finally{setLoading(false)}};
const signup=async(values)=>{setLoading(true);try{const r=await fetchWithTimeout(API+'/auth/signup',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,email:values.email.trim()})});if(r.status===409)throw Error('Account already exists. Please log in.');if(r.status===422){const e=await r.json();throw Error(Array.isArray(e.detail)?e.detail.map(x=>x.msg).join('. '):'Please check the information and try again.')}if(!r.ok){if(r.status===404)throw Error('Signup endpoint not found. Check the backend API URL.');let detail='';try{const e=await r.json();detail=typeof e.detail==='string'?e.detail:''}catch{}throw Error(detail||`Signup request failed (${r.status}). Please try again.`)}const data=await r.json();sessionStorage.setItem('token',data.access_token);sessionStorage.setItem('user',JSON.stringify(data.user));localStorage.removeItem('token');localStorage.removeItem('user');setToken(data.access_token);setUser(data.user);navigate('/',{replace:true})}finally{setLoading(false)}};
 if(checking)return <div className="loading"><LoaderCircle className="spin"/> Checking your session…</div>;
 if(!token)return <Routes><Route path="/signup" element={<Signup onSignup={signup} loading={loading}/>}/><Route path="*" element={<Login onLogin={login} loading={loading}/>}/></Routes>;
 if(location.pathname==='/login'||location.pathname==='/signup')return <Navigate to="/" replace/>;
 return <div className="app"><aside className={`sidebar ${collapsed?'collapsed':''}`}><div className="brand"><div className="brand-mark">B<span>↗</span></div>{!collapsed&&<div><b>BidFlow</b><small>COMPLIANCE WORKSPACE</small></div>}</div><div className="workspace"><span className="workspace-icon">N</span>{!collapsed&&<><div><b>Northstar Systems</b><small>Enterprise workspace</small></div><ChevronDown size={15}/></>}</div><div className="nav-label">WORKSPACE</div><nav><NavItem to="/" icon={<LayoutDashboard/>} label="Overview" collapsed={collapsed}/><NavItem to="/tenders" icon={<BriefcaseBusiness/>} label="Tenders" collapsed={collapsed}/><NavItem to="/compliance" icon={<ClipboardCheck/>} label="Compliance" collapsed={collapsed}/>{['Admin','Reviewer/Approver'].includes(user?.role)&&<NavItem to="/approvals" icon={<CheckCircle2/>} label="Review queue" collapsed={collapsed}/>}<NavItem to="/documents" icon={<FolderOpen/>} label="Documents" collapsed={collapsed}/><NavItem to="/reports" icon={<ChartNoAxesCombined/>} label="Reports" collapsed={collapsed}/></nav><div className="side-bottom"><NavItem to="/settings" icon={<Settings/>} label="Settings" collapsed={collapsed}/><button className="collapse" onClick={()=>setCollapsed(!collapsed)}><PanelLeftClose size={17}/>{!collapsed&&'Collapse sidebar'}</button><div className="profile"><div className="avatar">{user?.name?.[0]||'U'}</div>{!collapsed&&<><div className="profile-text"><b>{user?.name||'User'}</b><small>{user?.role}</small></div><button title="Sign out" onClick={logout}><LogOut size={16}/></button></>}</div></div></aside><main className="main"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setCollapsed(!collapsed)}><Menu/></button><div className="crumb">Workspace <span>/</span> <b>Overview</b></div><div className="top-actions"><div className="search"><Search size={16}/><input placeholder="Search tenders, documents..." onKeyDown={e=>e.key==='Enter'&&(location.href='/tenders?q='+encodeURIComponent(e.target.value))}/><kbd>⌘ K</kbd></div><button className="icon-button notification" onClick={async()=>{setNotificationOpen(!notificationOpen);if(!notificationOpen)try{setNotificationData(await req('/notifications'))}catch(e){setToast(e.message)}}}><Bell/>{notificationData.unread_count>0&&<i/>}</button><div className="top-avatar">{user?.name?.[0]||'U'}</div></div></header>{notificationOpen&&<NotificationPanel data={notificationData} close={()=>setNotificationOpen(false)} req={req} onUpdate={setNotificationData} navigate={navigate}/>}<div className="content">{location.pathname==="/"&&<div className="welcome-user"><b>Welcome, {user?.name||"User"}</b><span>{user?.email} · {user?.role}</span></div>}<Routes><Route path="/" element={<Dashboard req={req} toast={setToast}/>}/><Route path="/tenders" element={<Tenders req={req} toast={setToast}/>}/><Route path="/tenders/:id" element={<TenderPage req={req} toast={setToast} user={user}/>}/><Route path="/compliance" element={<Compliance req={req} toast={setToast}/>}/><Route path="/approvals" element={<ApprovalsQueue req={req}/>}/><Route path="/documents" element={<Documents req={req} toast={setToast}/>}/><Route path="/reports" element={<Reports req={req}/>}/><Route path="/settings" element={<SettingsPage req={req} user={user} onUser={setUser} toast={setToast}/>}/><Route path="*" element={<Dashboard req={req}/>}/></Routes></div></main>{toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}</div>}
function NavItem({to,icon,label,collapsed}){return <NavLink to={to} end={to==='/'} title={collapsed?label:''} className={({isActive})=>`nav-item ${isActive?'active':''}`}><span>{React.cloneElement(icon,{size:18})}</span>{!collapsed&&label}</NavLink>}
function AuthFrame({children}){return <div className="login-screen"><section className="login-art"><div className="brand light"><div className="brand-mark">B<span>↗</span></div><div><b>BidFlow</b><small>COMPLIANCE WORKSPACE</small></div></div><div className="art-copy"><span className="eyebrow">BID WITH CONFIDENCE</span><h1>Every detail.<br/><em>Under control.</em></h1><p>Your complete workspace for managing tenders, compliance, and winning work.</p><div className="art-card"><ShieldCheck/><div><b>Stay submission-ready</b><small>Know exactly what’s done and what still needs attention.</small></div></div></div><div className="art-foot">SECURE · ORGANIZED · READY TO WIN</div></section><section className="login-panel">{children}</section></div>}
function Login({onLogin,loading}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');const location=useLocation(),navigate=useNavigate();return <AuthFrame><div className="login-form"><span className="eyebrow">WELCOME BACK</span><h2>Sign in to BidFlow</h2><p>Enter your workspace credentials to continue.</p>{location.state?.success&&<div className="success-msg">{location.state.success}</div>}<form onSubmit={async e=>{e.preventDefault();if(loading)return;setError('');try{await onLogin(email,password)}catch(err){setError(err.message)}}}><label>Work email<input type="email" autoComplete="email" placeholder="you@company.com" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" autoComplete="current-password" placeholder="Enter your password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="error-msg" role="alert">{error}</div>}<button className="primary full" disabled={loading||!email.trim()||!password}>{loading?<><LoaderCircle className="spin"/> Signing in…</>:'Sign in'} {!loading&&<ArrowUpRight size={17}/>}</button></form><small className="setup-note">New to BidFlow? <button className="auth-link" onClick={()=>navigate('/signup')}>Create an account</button></small></div></AuthFrame>}
function Signup({onSignup,loading}){const [name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[error,setError]=useState('');const navigate=useNavigate();return <AuthFrame><div className="login-form"><span className="eyebrow">CREATE YOUR WORKSPACE ACCOUNT</span><h2>Sign up for BidFlow</h2><p>Use your work email to get started.</p><form onSubmit={async e=>{e.preventDefault();if(loading)return;setError('');if(password!==confirm){setError('Passwords do not match.');return}try{await onSignup({name,email,password})}catch(err){setError(err.message)}}}><label>Full name<input autoComplete="name" value={name} onChange={e=>setName(e.target.value)} required maxLength={160}/></label><label>Work email<input type="email" autoComplete="email" placeholder="you@company.com" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={12}/><small className="field-hint">Use at least 12 characters.</small></label><label>Confirm password<input type="password" autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} required minLength={12}/></label>{error&&<div className="error-msg" role="alert">{error}</div>}<button className="primary full" disabled={loading||!name.trim()||!email.trim()||password.length<12||!confirm}>{loading?<><LoaderCircle className="spin"/> Creating account…</>:'Create account'} {!loading&&<ArrowUpRight size={17}/>}</button></form><small className="setup-note">Already have an account? <button className="auth-link" onClick={()=>navigate('/login')}>Log in</button></small></div></AuthFrame>}
function useFetch(req,path){const [data,setData]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(true);const refresh=()=>{setBusy(true);req(path).then(setData).catch(e=>setError(e.message)).finally(()=>setBusy(false))};useEffect(()=>{refresh()},[path]);return {data,error,busy,refresh,setData}}
function PageHead({eyebrow,title,description,action}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Dashboard({req,toast}){const {data,error,busy}=useFetch(req,'/dashboard');const nav=useNavigate();if(busy)return <Loading/>;const d=data||{};const cards=[['Total tenders',d.total_tenders||0,'All opportunities','blue',BriefcaseBusiness],['Active bids',d.active_bids||0,'In progress','violet',ArrowUpRight],['Submitted bids',d.submitted_bids||0,'Awaiting outcome','green',CheckCircle2],['Needs attention',d.incomplete_compliance||0,'Compliance blockers','orange',AlertTriangle]];return <><PageHead eyebrow={new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase()} title="Bid overview" description="Here’s what’s happening across your bids today." action={<button className="primary" onClick={()=>nav('/tenders?new=1')}><Plus size={17}/> New tender</button>}/>{error&&<ErrorBox error={error}/>}<div className="kpi-grid">{cards.map(([title,value,sub,color,Icon])=><div className="kpi card" key={title} role="button" tabIndex={0} onClick={()=>nav(title==='Needs attention'?'/compliance?status=Missing':title==='Submitted bids'?'/tenders?status=Submitted':title==='Active bids'?'/tenders?active=1':'/tenders')}><div className="kpi-top"><span>{title}</span><i className={color}><Icon size={17}/></i></div><strong>{value}</strong><small><span className="dot green-dot"/> {sub}</small></div>)}</div><div className="insight-grid"><section className="card chart-card"><div className="section-head"><div><h3>Bid pipeline</h3><p>Opportunity status distribution</p></div><select><option>All time</option><option>This year</option></select></div><div className="pipeline"><div className="chart-wrap"><ResponsiveContainer width="100%" height={235}><BarChart data={(d.pipeline||[]).map(x=>({name:x.status.split(' ')[0],bids:x.count}))} barSize={32}><CartesianGrid vertical={false} stroke="#edf0f6"/><XAxis dataKey="name" tickLine={false} axisLine={false}/><YAxis allowDecimals={false} tickLine={false} axisLine={false}/><Tooltip/><Bar dataKey="bids" fill="#6558df" radius={[7,7,2,2]}/></BarChart></ResponsiveContainer></div><div className="pipeline-list">{(d.pipeline||[]).map((x,i)=><div key={x.status} role="button" tabIndex="0" onClick={()=>nav('/tenders?status='+encodeURIComponent(x.status))}><i className={`legend l${i}`}/><span>{x.status}</span><b>{x.count}</b></div>)}</div></div></section><section className="card deadlines"><div className="section-head"><div><h3>Compliance health</h3><p>Overall completion across active bids</p></div><button className="link" onClick={()=>nav('/compliance')}>View all <ArrowUpRight size={14}/></button></div><div className="health-score"><div className="ring" style={{'--percent':`${d.compliance_percent||0}%`}}><div>{d.compliance_percent||0}<small>%</small></div></div><div><b>{d.incomplete_compliance||0} items need attention</b><span>across active tenders</span></div></div><div className="health-line"><div><span>Pending approvals</span><b>{d.pending_approvals||0}</b></div><div><span>Upcoming deadlines</span><b>{d.upcoming_deadlines||0}</b></div><div><span>Overdue tasks</span><b className="red-text">{d.overdue_tasks||0}</b></div></div></section></div><section className="card activity-card"><div className="section-head"><div><h3>Recent activity</h3><p>The latest updates from your team</p></div><button className="link" onClick={()=>toast('Showing latest activity')}>View activity <ArrowUpRight size={14}/></button></div>{(d.recent_activity||[]).length?<div className="activity-list">{d.recent_activity.map((a,i)=><div className="activity-row" key={i}><div className="activity-icon"><FileText size={16}/></div><div><b>{a.action}</b><span>{a.entity} #{a.entity_id} {a.details&&'· '+a.details}</span></div><time>{a.created_at?new Date(a.created_at).toLocaleDateString():''}</time></div>)}</div>:<Empty text="Activity will appear here as your team works on bids."/>}</section></>}
function Tenders({req,toast}){const nav=useNavigate(),params=new URLSearchParams(location.search);const [q,setQ]=useState(params.get('q')||''),[filter,setFilter]=useState(params.get('status')||'All statuses'),[show,setShow]=useState(params.get('new')==='1');const {data,error,busy,refresh}=useFetch(req,'/tenders'+(q?'?q='+encodeURIComponent(q):''));return <><PageHead eyebrow="OPPORTUNITY TRACKER" title="Tenders" description="Manage every opportunity from discovery to outcome." action={<button className="primary" onClick={()=>setShow(true)}><Plus size={17}/> New tender</button>}/><div className="toolbar"><div className="table-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search tenders or clients"/></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All statuses</option>{['Draft','Not Started','In Progress','Pending Approval','Changes Requested','Approved','Rejected','Ready for Submission','Submitted','Closed','Won','Lost'].map(x=><option>{x}</option>)}</select><button className="secondary" onClick={refresh}>Refresh</button></div>{error&&<ErrorBox error={error}/>}<div className="card table-card"><table><thead><tr><th>TENDER / CLIENT</th><th>STATUS</th><th>OWNER</th><th>DEADLINE</th><th>PRIORITY</th><th/></tr></thead><tbody>{busy?<tr><td colSpan="6"><Loading/></td></tr>:(data||[]).filter(t=>params.get('active')==='1'?!['Submitted','Won','Lost','Closed','Cancelled'].includes(t.status):filter==='All statuses'||t.status===filter).map(t=><tr key={t.id} onClick={()=>nav(`/tenders/${t.id}`)}><td><b>{t.title}</b><small>{t.tender_code} · {t.client}</small></td><td><Status status={t.status}/></td><td><span className="owner"><i>{t.client?.[0]}</i>{t.owner_name||'Unassigned'}</span></td><td>{t.submission_deadline?new Date(t.submission_deadline+'T00:00:00').toLocaleDateString():'—'}</td><td><Priority value={t.priority}/></td><td><ArrowUpRight size={16}/></td></tr>)}</tbody></table>{!busy&&!data?.length&&<Empty text="Create your first tender to get started."/>}</div>{show&&<TenderModal req={req} close={()=>setShow(false)} done={()=>{setShow(false);refresh();toast('Tender created and checklist generated')}}/>}</>}
function TenderModal({req,close,done}){const [form,setForm]=useState({tender_code:'',title:'',client:'',department:'',submission_deadline:'',priority:'Medium',fee_required:false,emd_required:false}),[error,setError]=useState(''),[busy,setBusy]=useState(false);const save=async e=>{e.preventDefault();setBusy(true);setError('');try{await req('/tenders',{method:'POST',body:JSON.stringify({...form,submission_deadline:form.submission_deadline||null})});done()}catch(e){setError(e.message)}finally{setBusy(false)}};return <Modal title="Create a tender" close={close}><form className="modal-form" onSubmit={save}><div className="form-grid"><Field label="Tender ID" value={form.tender_code} onChange={v=>setForm({...form,tender_code:v})} required/><Field label="Tender title" value={form.title} onChange={v=>setForm({...form,title:v})} required/><Field label="Client" value={form.client} onChange={v=>setForm({...form,client:v})} required/><Field label="Department" value={form.department} onChange={v=>setForm({...form,department:v})}/><Field label="Submission deadline" type="date" value={form.submission_deadline} onChange={v=>setForm({...form,submission_deadline:v})}/><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{['Low','Medium','High','Critical'].map(x=><option>{x}</option>)}</select></label></div><div className="checks"><label><input type="checkbox" checked={form.fee_required} onChange={e=>setForm({...form,fee_required:e.target.checked})}/> Tender fee required</label><label><input type="checkbox" checked={form.emd_required} onChange={e=>setForm({...form,emd_required:e.target.checked})}/> EMD required</label></div>{error&&<ErrorBox error={error}/>}<div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={busy}>{busy?<LoaderCircle className="spin"/>:'Create tender'}</button></div></form></Modal>}
function TenderPage({req,toast,user}){const {id}=useParams(),{data,error,busy,refresh}=useFetch(req,`/tenders/${id}`);const [file,setFile]=useState(null);if(busy)return <Loading/>;if(error)return <ErrorBox error={error}/>;if(!data)return null;const upload=async c=>{if(!file)return;const f=new FormData();f.append('file',file);try{await req(`/tenders/${id}/documents?compliance_id=${c.id}`,{method:'POST',body:f});setFile(null);toast('File uploaded and marked pending review');refresh()}catch(e){toast(e.message)}};return <><PageHead eyebrow={data.tender_code} title={data.title} description={`${data.client} · ${data.department||'Department not specified'}`} action={<Status status={data.status}/>}/><div className="detail-stats"><div className="card"><small>Submission deadline</small><b>{data.submission_deadline||'Not set'}</b></div><div className="card"><small>Priority</small><Priority value={data.priority}/></div><div className="card"><small>Compliance items</small><b>{data.compliance?.length||0}</b></div></div><OwnerAssignment tender={data} req={req} user={user} onSaved={refresh}/><div className="card compliance-card"><div className="section-head"><div><h3>Compliance checklist</h3><p>Upload evidence and route each requirement for approval.</p></div><button className="secondary" onClick={()=>req(`/tenders/${id}/readiness`).then(x=>toast(x.ready?'Ready for submission':`${x.blockers.length} readiness blockers`)).catch(e=>toast(e.message))}>Check readiness</button></div>{data.compliance?.map(c=><div className="compliance-row" key={c.id}><div className="compliance-heading"><div><b>{c.title}</b><small>{c.required_fields.length} fields · {c.required_attachments.length} required attachments</small></div><Status status={c.status}/></div><ComplianceAssignment item={c} req={req} user={user} onSaved={refresh}/><ComplianceForm item={c} req={req} toast={toast}/>{['Admin','Bid Manager'].includes(user?.role)&&<button className="link" onClick={async()=>{const notes=window.prompt('Explain why this requirement does not apply to this tender');if(!notes)return;try{await req('/compliance/'+c.id,{method:'PATCH',body:JSON.stringify({status:'Not Required',notes})});toast('Requirement marked not applicable');refresh()}catch(e){toast(e.message)}}}>Mark not required</button>}{c.required_attachments.length>0&&<div className="attachment-hint">Required: {c.required_attachments.join(' · ')}</div>}<div className="compliance-actions"><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/><button className="secondary" disabled={!file} onClick={()=>upload(c)}><Upload size={15}/> Upload evidence</button><button className="primary" onClick={async()=>{try{await req(`/compliance/${c.id}/submit-review`,{method:'POST'});toast('Submitted for review');refresh()}catch(e){toast(e.message)}}}>Submit for review</button>{['Admin','Reviewer/Approver'].includes(user?.role)&&<><button className="secondary" onClick={async()=>{const comments=window.prompt('Optional reviewer comment')||'';try{await req(`/compliance/${c.id}/approval`,{method:'POST',body:JSON.stringify({action:'Approved',comments})});toast('Requirement approved');refresh()}catch(e){toast(e.message)}}}>Approve</button><button className="secondary" onClick={async()=>{const comments=window.prompt('Enter rejection reason');if(!comments)return;try{await req(`/compliance/${c.id}/approval`,{method:'POST',body:JSON.stringify({action:'Rejected',comments})});toast('Requirement rejected');refresh()}catch(e){toast(e.message)}}}>Reject</button><button className="secondary" onClick={async()=>{const comments=window.prompt('Describe the changes required');if(!comments)return;try{await req(`/compliance/${c.id}/approval`,{method:'POST',body:JSON.stringify({action:'Changes Requested',comments})});toast('Changes requested');refresh()}catch(e){toast(e.message)}}}>Request changes</button></>}</div></div>)}</div></>}
function OwnerAssignment({tender,req,user,onSaved}){const [users,setUsers]=useState([]),[owner,setOwner]=useState(tender.owner_id||''),[busy,setBusy]=useState(false);useEffect(()=>{req('/users/assignable').then(setUsers).catch(()=>{})},[]);const allowed=['Admin','Bid Manager'].includes(user?.role);return <section className="card owner-assignment"><div><b>Tender owner</b><small>{tender.owner_name?tender.owner_name+' · '+(tender.owner_role||''):'No owner assigned'}</small></div>{allowed?<div className="owner-controls"><select value={owner} onChange={e=>setOwner(e.target.value)}><option value="">Unassigned</option>{users.map(x=><option key={x.id} value={x.id}>{x.name} · {x.role}</option>)}</select><button className="secondary" disabled={busy} onClick={async()=>{setBusy(true);try{await req('/tenders/'+tender.id,{method:'PATCH',body:JSON.stringify({owner_id:owner?Number(owner):null})});onSaved()}catch(e){window.alert(e.message)}finally{setBusy(false)}}}>{busy?'Saving…':'Save owner'}</button></div>:<small>Owner assignment is managed by a bid manager.</small>}</section>}
function ComplianceAssignment({item,req,user,onSaved}){const [users,setUsers]=useState([]),[owner,setOwner]=useState(item.owner_id||''),[due,setDue]=useState(item.due_date||''),[busy,setBusy]=useState(false);const allowed=['Admin','Bid Manager'].includes(user?.role);useEffect(()=>{if(allowed)req('/users/assignable').then(setUsers).catch(()=>{})},[allowed]);return <div className="compliance-assignment"><label>Owner{allowed?<select value={owner} onChange={e=>setOwner(e.target.value)}><option value="">Unassigned</option>{users.map(x=><option key={x.id} value={x.id}>{x.name} · {x.role}</option>)}</select>:<span>{item.owner_id||'Unassigned'}</span>}</label><label>Due date<input type="date" value={due} onChange={e=>setDue(e.target.value)}/></label>{allowed&&<button className="secondary" disabled={busy} onClick={async()=>{setBusy(true);try{await req('/compliance/'+item.id,{method:'PATCH',body:JSON.stringify({owner_id:owner?Number(owner):null,due_date:due||null})});onSaved()}catch(e){window.alert(e.message)}finally{setBusy(false)}}}>{busy?'Saving…':'Save assignment'}</button>}</div>}
function ComplianceForm({item,req,toast}){const [values,setValues]=useState(item.data||{}),[saving,setSaving]=useState(false);return <details className="field-details"><summary>Requirement details</summary><div className="compliance-fields">{item.required_fields.map(field=><label key={field}>{field}<input value={values[field]||''} onChange={e=>setValues({...values,[field]:e.target.value})}/></label>)}<button className="secondary" disabled={saving} onClick={async()=>{setSaving(true);try{await req(`/compliance/${item.id}`,{method:'PATCH',body:JSON.stringify({data_json:values})});toast('Requirement details saved')}catch(e){toast(e.message)}finally{setSaving(false)}}}>{saving?'Saving…':'Save details'}</button></div></details>}
function Compliance({req}){const {data:ts,error,busy}=useFetch(req,'/tenders');const [items,setItems]=useState([]),[filter,setFilter]=useState(new URLSearchParams(location.search).get('status')||'All statuses');useEffect(()=>{if(ts)Promise.all(ts.map(t=>req(`/tenders/${t.id}/compliance`).then(cs=>cs.map(c=>({...c,tender_name:t.title,tender_code:t.tender_code}))))).then(x=>setItems(x.flat())).catch(()=>{})},[ts]);return <><PageHead eyebrow="REQUIREMENTS & APPROVALS" title="Compliance" description="Track required evidence, owners, and approvals across tenders."/><div className="toolbar"><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All statuses</option>{['Not Started','Missing','In Progress','Pending Approval','Changes Requested','Approved','Rejected'].map(x=><option key={x}>{x}</option>)}</select>{filter!=='All statuses'&&<button className="secondary" onClick={()=>setFilter('All statuses')}>Clear filter</button>}</div><div className="card table-card"><table><thead><tr><th>REQUIREMENT</th><th>TENDER</th><th>OWNER</th><th>DUE DATE</th><th>STATUS</th><th/></tr></thead><tbody>{busy?<tr><td colSpan="6"><Loading/></td></tr>:items.filter(c=>filter==='All statuses'||c.status===filter||(filter==='Not Started'&&c.status==='Missing')).map(c=><tr key={c.id}><td><b>{c.title}</b><small>{c.required_fields.length} fields · {c.required_attachments.length} attachments</small></td><td>{c.tender_code}<small>{c.tender_name}</small></td><td>{c.owner_id||'Unassigned'}</td><td>{c.due_date||'—'}</td><td><Status status={c.status}/></td><td><NavLink to={`/tenders/${c.tender_id}`} className="link">Open</NavLink></td></tr>)}</tbody></table>{!busy&&!items.filter(c=>filter==='All statuses'||c.status===filter||(filter==='Not Started'&&c.status==='Missing')).length&&<Empty text={filter==='All statuses'?'Compliance checklists appear when a tender is created.':`No ${filter.toLowerCase()} requirements found.`}/>}</div>{error&&<ErrorBox error={error}/>}</>}
function ApprovalsQueue({req}){const {data,error,busy}=useFetch(req,'/approvals/pending'),nav=useNavigate();return <><PageHead eyebrow="REVIEWER WORKSPACE" title="Review queue" description="Compliance submissions waiting for an authorized review decision."/><div className="card table-card"><table><thead><tr><th>REQUIREMENT</th><th>TENDER</th><th>OWNER ID</th><th>DUE DATE</th><th>STATUS</th><th/></tr></thead><tbody>{busy?<tr><td colSpan="6"><Loading/></td></tr>:(data||[]).map(x=><tr key={x.id}><td><b>{x.title}</b><small>{x.category}</small></td><td>{x.tender_code}<small>{x.tender_title}</small></td><td>{x.owner_id||'Unassigned'}</td><td>{x.due_date||'—'}</td><td><Status status={x.status}/></td><td><button className="link" onClick={()=>nav('/tenders/'+x.tender_id)}>Review</button></td></tr>)}</tbody></table>{!busy&&!data?.length&&<Empty text="No submissions are waiting for review."/>}{error&&<ErrorBox error={error}/>}</div></>}
function Documents({req}){const {data:ts,error,busy}=useFetch(req,'/tenders');return <><PageHead eyebrow="DOCUMENT LIBRARY" title="Documents" description="Find and manage files attached to your tender records."/><div className="card document-intro"><div className="doc-illustration"><FolderOpen size={25}/></div><div><h3>Tender documents</h3><p>Documents are securely stored with tender records. Upload an RFP from its tender detail page and attach evidence to a compliance requirement.</p></div><button className="secondary" onClick={()=>location.href='/tenders'}>Browse tenders <ArrowUpRight size={15}/></button></div><div className="card table-card"><table><thead><tr><th>TENDER</th><th>CLIENT</th><th>DEADLINE</th><th>STATUS</th><th/></tr></thead><tbody>{busy?<tr><td colSpan="5"><Loading/></td></tr>:(ts||[]).map(t=><tr key={t.id}><td><b>{t.title}</b><small>{t.tender_code}</small></td><td>{t.client}</td><td>{t.submission_deadline||'—'}</td><td><Status status={t.status}/></td><td><NavLink to={`/tenders/${t.id}`} className="link">Manage files</NavLink></td></tr>)}</tbody></table></div>{error&&<ErrorBox error={error}/>}</>}
function Reports({req}){const [error,setError]=useState('');const download=async()=>{try{const savedToken=sessionStorage.getItem('token')||localStorage.getItem('token');const r=await fetchWithTimeout(API+'/reports/readiness.csv',{headers:{Authorization:`Bearer ${savedToken}`}});if(!r.ok)throw Error('Report download failed');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='bid-readiness.csv';a.click();URL.revokeObjectURL(url)}catch(e){setError(e.message)}};return <><PageHead eyebrow="INSIGHTS & EXPORTS" title="Reports" description="Submission readiness reports backed by live tender and compliance data." action={<button className="primary" onClick={download}><Download size={16}/> Download readiness CSV</button>}/>{error&&<ErrorBox error={error}/>}<div className="report-grid"><div className="card report-card"><div className="report-icon violet"><ShieldCheck/></div><h3>Bid readiness</h3><p>Outstanding blockers, responsible owners, due dates, and approval status.</p><button className="secondary" onClick={download}>Download CSV <ArrowUpRight size={14}/></button></div><div className="card report-card"><div className="report-icon blue"><Clock3/></div><h3>Deadline tracking</h3><p>Upcoming submission dates and overdue work across the active pipeline.</p><NavLink to="/" className="secondary">View dashboard <ArrowUpRight size={14}/></NavLink></div><div className="card report-card"><div className="report-icon orange"><FileText/></div><h3>Missing documents</h3><p>Review requirements that still need evidence or an approval decision.</p><NavLink to="/compliance" className="secondary">View compliance <ArrowUpRight size={14}/></NavLink></div></div></>}
function NotificationPanel({data,close,req,onUpdate,navigate}){const mark=async(id)=>{try{await req('/notifications/'+id,{method:'PATCH',body:JSON.stringify({read:true})});onUpdate({...data,unread_count:Math.max(0,data.unread_count-1),items:data.items.map(n=>n.id===id?{...n,read:true}:n)})}catch(e){}};return <div className="notification-panel card"><div className="section-head"><div><h3>Notifications</h3><p>{data.unread_count||0} unread</p></div><button className="link" onClick={async()=>{await req('/notifications/read-all',{method:'POST'});onUpdate({...data,unread_count:0,items:data.items.map(n=>({...n,read:true}))})}}>Mark all read</button><button className="icon-button" onClick={close}><X size={16}/></button></div>{data.items.length?data.items.map(n=><button key={n.id} className={'notification-row '+(n.read?'read':'')} onClick={async()=>{if(!n.read)await mark(n.id);close();const match=n.body.match(/#(\d+)/);navigate(match?'/tenders/'+match[1]:'/tenders')}}><b>{n.title}</b><span>{n.body}</span><small>{new Date(n.created_at).toLocaleString()}</small></button>):<Empty text="No notifications yet. Updates about your assigned bids will appear here."/>}</div>}
function SettingsPage({req,user,onUser,toast}){const [name,setName]=useState(user?.name||''),[contacts,setContacts]=useState([]),[error,setError]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{req('/admin/compliance-contacts').then(setContacts).catch(e=>setError(e.message))},[]);const save=async e=>{e.preventDefault();setBusy(true);try{const next=await req('/auth/me',{method:'PATCH',body:JSON.stringify({name})});onUser(next);sessionStorage.setItem('user',JSON.stringify(next));toast('Profile updated')}catch(e){setError(e.message)}finally{setBusy(false)}};return <><PageHead eyebrow="WORKSPACE" title="Profile & settings" description="Manage your profile and review the configurable compliance directory."/><div className="settings-grid"><section className="card settings-card"><h3>Your profile</h3><p>These details belong to your authenticated account.</p><form onSubmit={save}><label>Full name<input value={name} onChange={e=>setName(e.target.value)} required maxLength={160}/></label><label>Email<input value={user?.email||''} disabled/></label><label>Role<input value={user?.role||''} disabled/></label><button className="primary" disabled={busy}>{busy?'Saving…':'Save profile'}</button></form></section><section className="card settings-card"><h3>Compliance contacts</h3><p>Source details are editable by administrators. Missing source email or phone values are left blank.</p>{error&&<ErrorBox error={error}/>}<div className="contact-list">{contacts.length?contacts.map(c=><div key={c.id}><b>{c.name}</b><span>{c.category} · {c.responsibility}</span><small>{c.email||'Email not recorded'} · {c.phone||'Phone not recorded'}</small>{user?.role==='Admin'&&<button className="link" onClick={async()=>{const responsibility=window.prompt('Contact responsibility',c.responsibility);if(responsibility===null)return;const email=window.prompt('Contact email (leave blank if not provided)',c.email||'');if(email===null)return;const phone=window.prompt('Contact phone (leave blank if not provided)',c.phone||'');if(phone===null)return;try{const updated=await req('/admin/compliance-contacts/'+c.id,{method:'PATCH',body:JSON.stringify({responsibility,email,phone})});setContacts(contacts.map(x=>x.id===c.id?updated:x));toast('Contact updated')}catch(e){setError(e.message)}}}>Edit contact</button>}</div>):<Empty text="No contact records configured yet."/>}</div>{user?.role==='Admin'&&<ContactEditor req={req} onAdd={c=>setContacts([...contacts,c])} toast={toast}/>}</section></div></>}
function ContactEditor({req,onAdd,toast}){const [form,setForm]=useState({name:'',responsibility:'',category:'General'}),[busy,setBusy]=useState(false);return <form className="contact-editor" onSubmit={async e=>{e.preventDefault();setBusy(true);try{const c=await req('/admin/compliance-contacts',{method:'POST',body:JSON.stringify(form)});onAdd(c);setForm({name:'',responsibility:'',category:'General'});toast('Contact added')}catch(e){toast(e.message)}finally{setBusy(false)}}}><input placeholder="Contact name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/><input placeholder="Responsibility" value={form.responsibility} onChange={e=>setForm({...form,responsibility:e.target.value})} required/><input placeholder="Category" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}/><button className="secondary" disabled={busy}>{busy?'Adding…':'Add contact'}</button></form>}
function Field({label,value,onChange,type='text',required}){return <label>{label}<input type={type} value={value} onChange={e=>onChange(e.target.value)} required={required}/></label>};function Status({status=''}){let s=status.toLowerCase().replaceAll(' ','-');return <span className={`badge ${s.includes('approv')||s==='won'||s==='submitted'?'success':s.includes('missing')||s==='rejected'||s.includes('overdue')?'danger':s.includes('ready')?'ready':s.includes('progress')?'progress':'neutral'}`}><i/>{status||'Unknown'}</span>};function Priority({value}){return <span className={`priority ${value?.toLowerCase()}`}>● {value||'Medium'}</span>};function Loading(){return <div className="loading"><LoaderCircle className="spin"/> Loading workspace…</div>};function ErrorBox({error}){return <div className="error-box"><AlertTriangle size={17}/>{String(error)}</div>};function Empty({text}){return <div className="empty"><div><FileText size={21}/></div><p>{text}</p></div>};function Modal({title,close,children}){return <div className="modal-backdrop" onMouseDown={close}><div className="modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button onClick={close}><X size={18}/></button></div>{children}</div></div>}
export default App;
import React,{useEffect,useState} from 'react';
